        nz_vals = [(grid[row][col], 1) for row in range(h) if grid[row][col] != 0]
        if nz_vals:
            # Find most common non-zero value
            mode = max(set(v for v, _ in nz_vals), key=lambda v: sum(1 for av, _ in nz_vals if av == v))
            count = sum(1 for av, _ in nz_vals if av == mode)
            freq = count / sum(counts := sum(1 for _, c in nz_vals) for counts) if nz_vals else 0

            # Actually simpler: just use percentage
