        if freq >= 0.9 and mode_count > h * 0.5:
            vlines.append({'col': col, 'value': mode_val})

    return sorted(vlines, key=lambda x: x['col'])

def predict_grid(inp, out_actual=None):
    h, w = len(inp), len(inp[0])
    vlines = find_vlines_dominant(inp)

    # Find region values from content rows
    seen_regions = set()
    regions = []
    for row_idx in range(h):
        for i in range(w):
            if i not in [vl['col'] for vl in vlines]:
                v = inp[row_idx][i]
                if v != 0 and v not in seen_regions:
