import json, re, os

def load():
    d=os.environ['RLM_SESSION_DIR']
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n')
    G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G

G = load()

def find_vlines(grid):
    h, w = len(grid), len(grid[0])
    vlines = []
    for col in range(w):
        counts = {}
        for row in range(h):
            v = grid[row][col]
            if v != 0:
                counts[v] = counts.get(v, 0) + 1

        if not counts:
            continue

        mode_val, mode_count = max(counts.items(), key=lambda x: x[1])
        freq = mode_count / h

        if freq >= 0.9:
            vlines.append({'col': col, 'value': mode_val})

    return sorted(vlines, key=lambda x: x['col'])

test_input = G['Test input']
vl_cols = {v['col'] for v in find_vlines(test_input)}

all_colors = set()
for row in test_input:
    for col, val in enumerate(row):
        if col not in vl_cols and val != 0:
            all_colors.add(val)

color_metrics = {}
for c in all_colors:
    total_pixels = 0
    row_count = 0
    has_complete_row = False

    for row_idx, row in enumerate(test_input):
        nz_in_row = 0
        c_in_row = 0
        for col, val in enumerate(row):
            if col not in vl_cols:
                if val != 0:
                    nz_in_row += 1
                    if val == c:
                        c_in_row += 1
        total_pixels += c_in_row
        if c_in_row > 0:
            row_count += 1
        if nz_in_row > 0 and c_in_row == nz_in_row:
            has_complete_row = True

    color_metrics[c] = {
        'pixels': total_pixels,
        'rows': row_count,
        'has_complete_row': has_complete_row
    }

# Sort ALL colors properly
sorted_colors = sorted(color_metrics.keys(), 
                      key=lambda c: (-color_metrics[c]['has_complete_row'], 
                                    -color_metrics[c]['pixels'], 
                                    c))

print(f"Sorted: {sorted_colors}")
print(f"Last 2: {sorted_colors[-2:]}")

num_vlines = len(find_vlines(test_input))
out_w = 2 * num_vlines + 1
out_h = 5
vlines = find_vlines(test_input)

last2 = sorted_colors[-2:]
